import graphene
from django.core.exceptions import ValidationError

from ....account.models import User
from ....giftcard.utils import order_has_gift_card_lines
from ....order import FulfillmentStatus
from ....order.actions import cancel_fulfillment
from ....order.error_codes import OrderErrorCode
from ....permission.enums import OrderPermissions
from ...app.dataloaders import get_app_promise
from ...core import ResolveInfo
from ...core.context import SyncWebhookControlContext
from ...core.doc_category import DOC_CATEGORY_ORDERS
from ...core.mutations import BaseMutation
from ...core.types import BaseInputObjectType, OrderError
from ...plugins.dataloaders import get_plugin_manager_promise
from ...site.dataloaders import get_site_promise
from ...warehouse.types import Warehouse
from ..types import Fulfillment, Order


class FulfillmentCancelInput(BaseInputObjectType):
    warehouse_id = graphene.ID(
        description="ID of a warehouse where items will be restocked. Optional "
        "when fulfillment is in WAITING_FOR_APPROVAL state.",
        required=False,
    )

    class Meta:
        doc_category = DOC_CATEGORY_ORDERS


class FulfillmentCancel(BaseMutation):
    fulfillment = graphene.Field(Fulfillment, description="A canceled fulfillment.")
    order = graphene.Field(Order, description="Order which fulfillment was cancelled.")

    class Arguments:
        id = graphene.ID(required=True, description="ID of a fulfillment to cancel.")
        input = FulfillmentCancelInput(
            required=False, description="Fields required to cancel a fulfillment."
        )

    class Meta:
        description = "Cancels existing fulfillment and optionally restocks items."
        doc_category = DOC_CATEGORY_ORDERS
        permissions = (OrderPermissions.MANAGE_ORDERS,)
        error_type_class = OrderError
        error_type_field = "order_errors"

    @classmethod
    def validate_fulfillment(cls, fulfillment, warehouse):
        if not fulfillment.can_edit():
            raise ValidationError(
                {
                    "fulfillment": ValidationError(
                        "This fulfillment can't be canceled",
                        code=OrderErrorCode.CANNOT_CANCEL_FULFILLMENT.value,
                    )
                }
            )
        if (
            fulfillment.status != FulfillmentStatus.WAITING_FOR_APPROVAL
            and not warehouse
        ):
            raise ValidationError(
                {
                    "warehouseId": ValidationError(
                        "This parameter is required for fulfillments which are not in "
                        "WAITING_FOR_APPROVAL state.",
                        code=OrderErrorCode.REQUIRED.value,
                    )
                }
            )

    @classmethod
    def validate_order(cls, order):
        if order_has_gift_card_lines(order):
            raise ValidationError(
                {
                    "fulfillment": ValidationError(
                        "Cannot cancel fulfillment with gift card lines.",
                        code=OrderErrorCode.CANNOT_CANCEL_FULFILLMENT.value,
                    )
                }
            )
        return order

    @classmethod
    def perform_mutation(  # type: ignore[override]
        cls, _root, info: ResolveInfo, /, *, id: str, input=None
    ):
        user = info.context.user
        user = cast(User, user)
        fulfillment = cls.get_node_or_error(info, id, only_type=Fulfillment)
        order = fulfillment.order
        cls.check_channel_permissions(info, [order.channel_id])

        cls.validate_order(order)

        warehouse = None
        if fulfillment.status == FulfillmentStatus.WAITING_FOR_APPROVAL:
            warehouse = None
        elif input:
            warehouse_id: str | None = input.get("warehouse_id")
            if warehouse_id:
                warehouse = cls.get_node_or_error(
                    info, warehouse_id, only_type=Warehouse, field="warehouse_id"
                )

        cls.validate_fulfillment(fulfillment, warehouse)

        app = get_app_promise(info.context).get()
        manager = get_plugin_manager_promise(info.context).get()
        site_settings = get_site_promise(info.context).get().settings
        calculate_stocks_with_shipping_zones = (
            site_settings.use_legacy_shipping_zone_stock_availability
        )
        fulfillment = cancel_fulfillment(
            fulfillment,
            user,
            app,
            warehouse,
            manager,
            calculate_stocks_with_shipping_zones=calculate_stocks_with_shipping_zones,
        )
        fulfillment_response = SyncWebhookControlContext(node=fulfillment)
        order.refresh_from_db(fields=["status"])
        return FulfillmentCancel(
            fulfillment=fulfillment_response, order=SyncWebhookControlContext(order)
        )

from uuid import UUID

import graphene
from django.core.exceptions import ValidationError

from ....giftcard.utils import order_has_gift_card_lines
from ....order import FulfillmentLineData
from ....order import models as order_models
from ....order.error_codes import OrderErrorCode
from ....order.fetch import OrderLineInfo
from ....page.models import Page, PageType
from ....site.models import SiteSettings
from ...core.mutations import BaseMutation
from ...payment.utils import validate_reason_reference_context
from ..types import FulfillmentLine, OrderLine
from .order_grant_refund_utils import resolve_reason_reference_page


class FulfillmentRefundAndReturnProductBase(BaseMutation):
    class Meta:
        abstract = True

    @classmethod
    def _resolve_line_reason_reference(
        cls,
        reason_reference_id: str | None,
        site_settings: SiteSettings | None,
        reason_reference_type: PageType | None,
    ) -> Page | None:
        """Validate and resolve a per-line reason reference to a Page.

        Per-line references are always optional (for both staff and apps); when
        provided the referenced Page must match the configured reference type.
        Reason processing is skipped entirely when ``site_settings`` is not given.
        """
        if not site_settings or reason_reference_id is None:
            return None
        should_apply = validate_reason_reference_context(
            reason_reference_id=reason_reference_id,
            requestor_is_user=False,
            reason_reference_field_name="reason_reference",
            error_code_enum=OrderErrorCode,
            reason_reference_type=reason_reference_type,
        )
        if should_apply and reason_reference_type:
            return resolve_reason_reference_page(
                str(reason_reference_id), reason_reference_type.pk, OrderErrorCode
            )
        return None

    @classmethod
    def clean_order_payment(cls, payment, cleaned_input):
        if not payment or not payment.can_refund():
            raise ValidationError(
                {
                    "order": ValidationError(
                        "Order cannot be refunded.",
                        code=OrderErrorCode.CANNOT_REFUND.value,
                    )
                }
            )
        cleaned_input["payment"] = payment

    @classmethod
    def clean_amount_to_refund(
        cls, order, amount_to_refund, charged_value, cleaned_input
    ):
        if amount_to_refund is not None:
            if order_has_gift_card_lines(order):
                raise ValidationError(
                    {
                        "amount_to_refund": ValidationError(
                            (
                                "Cannot specified amount to refund when order has "
                                "gift card lines."
                            ),
                            code=OrderErrorCode.CANNOT_REFUND.value,
                        )
                    }
                )

            if amount_to_refund > charged_value:
                raise ValidationError(
                    {
                        "amount_to_refund": ValidationError(
                            (
                                "The amountToRefund is greater than the maximal "
                                "possible amount to refund."
                            ),
                            code=OrderErrorCode.CANNOT_REFUND.value,
                        ),
                    }
                )
        cleaned_input["amount_to_refund"] = amount_to_refund

    @classmethod
    def _raise_error_for_line(cls, msg, type, line_id, field_name, code=None):
        line_global_id = graphene.Node.to_global_id(type, line_id)
        if not code:
            code = OrderErrorCode.INVALID_QUANTITY.value
        raise ValidationError(
            {
                field_name: ValidationError(
                    msg,
                    code=code,
                    params={field_name: line_global_id},
                )
            }
        )

    @classmethod
    def raise_error_for_payment_error(cls):
        msg = "The refund operation is not available yet."
        code = OrderErrorCode.CANNOT_REFUND.value
        raise ValidationError(
            msg,
            code=code,
        )

    @classmethod
    def clean_fulfillment_lines(
        cls,
        fulfillment_lines_data,
        cleaned_input,
        whitelisted_statuses,
        site_settings: SiteSettings | None = None,
        reason_reference_type: PageType | None = None,
    ):
        fulfillment_lines = cls.get_nodes_or_error(
            [line["fulfillment_line_id"] for line in fulfillment_lines_data],
            field="fulfillment_lines",
            only_type=FulfillmentLine,
            qs=order_models.FulfillmentLine.objects.prefetch_related(
                "fulfillment", "order_line"
            ),
        )
        fulfillment_lines = list(fulfillment_lines)
        cleaned_fulfillment_lines = []
        for line, line_data in zip(
            fulfillment_lines, fulfillment_lines_data, strict=False
        ):
            quantity = line_data["quantity"]
            if line.order_line.is_gift_card:
                cls._raise_error_for_line(
                    "Cannot refund or return gift card line.",
                    "FulfillmentLine",
                    line.pk,
                    "fulfillment_line_id",
                    OrderErrorCode.GIFT_CARD_LINE.value,
                )
            if line.quantity < quantity:
                cls._raise_error_for_line(
                    "Provided quantity is bigger than quantity from fulfillment line",
                    "FulfillmentLine",
                    line.pk,
                    "fulfillment_line_id",
                )
            if line.fulfillment.status not in whitelisted_statuses:
                allowed_statuses_str = ", ".join(whitelisted_statuses)
                cls._raise_error_for_line(
                    f"Unable to process action for fulfillmentLine with different "
                    f"status than {allowed_statuses_str}.",
                    "FulfillmentLine",
                    line.pk,
                    "fulfillment_line_id",
                    code=OrderErrorCode.INVALID.value,
                )
            replace = line_data.get("replace", False)
            if replace and not line.order_line.variant_id:
                cls._raise_error_for_line(
                    "Unable to replace line as the assigned product doesn't exist.",
                    "OrderLine",
                    line.pk,
                    "order_line_id",
                )
            reason_reference_instance = cls._resolve_line_reason_reference(
                line_data.get("reason_reference"),
                site_settings,
                reason_reference_type,
            )
            cleaned_fulfillment_lines.append(
                FulfillmentLineData(
                    line=line,
                    quantity=quantity,
                    replace=replace,
                    reason=line_data.get("reason"),
                    reason_reference=reason_reference_instance,
                )
            )
        cleaned_input["fulfillment_lines"] = cleaned_fulfillment_lines

    @classmethod
    def clean_lines(
        cls,
        lines_data,
        cleaned_input,
        site_settings: SiteSettings | None = None,
        reason_reference_type: PageType | None = None,
    ):
        order_lines = cls.get_nodes_or_error(
            [line["order_line_id"] for line in lines_data],
            field="order_lines",
            only_type=OrderLine,
            qs=order_models.OrderLine.objects.prefetch_related(
                "fulfillment_lines__fulfillment", "variant", "allocations"
            ),
        )
        order_lines = list(order_lines)
        cleaned_order_lines = []
        order_lines_reason_data: dict[UUID, tuple[str | None, Page | None]] = {}
        for line, line_data in zip(order_lines, lines_data, strict=False):
            quantity = line_data["quantity"]
            if line.is_gift_card:
                cls._raise_error_for_line(
                    "Cannot refund or return gift card line.",
                    "OrderLine",
                    line.pk,
                    "order_line_id",
                    OrderErrorCode.GIFT_CARD_LINE.value,
                )
            if line.quantity < quantity:
                cls._raise_error_for_line(
                    "Provided quantity is bigger than quantity from order line.",
                    "OrderLine",
                    line.pk,
                    "order_line_id",
                )
            quantity_ready_to_move = line.quantity_unfulfilled
            if quantity_ready_to_move < quantity:
                cls._raise_error_for_line(
                    "Provided quantity is bigger than unfulfilled quantity.",
                    "OrderLine",
                    line.pk,
                    "order_line_id",
                )
            variant = line.variant
            replace = line_data.get("replace", False)
            if replace and not line.variant_id:
                cls._raise_error_for_line(
                    "Unable to replace line as the assigned product doesn't exist.",
                    "OrderLine",
                    line.pk,
                    "order_line_id",
                )

            reason_reference_instance = cls._resolve_line_reason_reference(
                line_data.get("reason_reference"),
                site_settings,
                reason_reference_type,
            )
            cleaned_order_lines.append(
                OrderLineInfo(
                    line=line, quantity=quantity, variant=variant, replace=replace
                )
            )
            order_lines_reason_data[line.pk] = (
                line_data.get("reason"),
                reason_reference_instance,
            )
        cleaned_input["order_lines"] = cleaned_order_lines
        cleaned_input["order_lines_reason_data"] = order_lines_reason_data

